import Foundation
import Testing
import SwiftData
@testable import PacerCore

/// The rate-limit record grades the value the user is shown (#300): the
/// anchored, clamped end-at-reset value, in Swift and in the Python harness
/// alike. The parity fixture is generated by
/// `research/harness/pacer_replay.py --emit-parity-fixture`; if either side's
/// scoring drifts, the first test fails.
@Suite("Rate-limit record scores the displayed value")
struct RLDisplayedParityTests {

    static var utc: Calendar {
        var c = Calendar(identifier: .gregorian); c.timeZone = TimeZone(identifier: "UTC")!; return c
    }

    struct Fixture: Decodable {
        struct CycleRow: Decodable { let cycleStart: Double; let resetsAt: Double; let samples: [[Double]] }
        struct Row: Decodable { let cycle: Int; let bucket: String; let method: String; let predicted: Double; let truth: Double }
        let bucketVersion: String
        let cycles: [CycleRow]
        let rows: [Row]
    }

    static func fixture() throws -> Fixture {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent()
            .deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("research/harness/fixtures/rl_displayed_parity.json")
        return try JSONDecoder().decode(Fixture.self, from: Data(contentsOf: url))
    }

    static func cycles(_ f: Fixture) -> [BurnTrajectory.Cycle] {
        f.cycles.map { c in
            BurnTrajectory.Cycle(
                samples: c.samples.map { .init(at: Date(timeIntervalSince1970: $0[0]), usedPercentage: $0[1]) },
                cycleStart: Date(timeIntervalSince1970: c.cycleStart),
                resetsAt: Date(timeIntervalSince1970: c.resetsAt))
        }
    }

    @Test func swiftRecordMatchesThePythonHarness() throws {
        let f = try Self.fixture()
        #expect(f.bucketVersion == EngineSelfEval.rlBucketVersion)
        let cycles = Self.cycles(f)
        let out = EngineSelfEval.newOutcomesRL(
            window: "five_hour", cycles: cycles, activityGrid: [], calendar: Self.utc,
            existingKeys: [], includeDiurnal: false)
        let periodIndex = Dictionary(uniqueKeysWithValues: cycles.enumerated().map {
            (EngineSelfEval.periodKeyRL($0.element.resetsAt), $0.offset)
        })
        let swift = Dictionary(uniqueKeysWithValues: out.map {
            ("\(periodIndex[$0.periodKey]!)|\($0.bucket)|\($0.method)", $0)
        })
        let python = Dictionary(uniqueKeysWithValues: f.rows.map { ("\($0.cycle)|\($0.bucket)|\($0.method)", $0) })
        #expect(Set(swift.keys) == Set(python.keys))
        for (key, p) in python {
            guard let s = swift[key] else { continue }
            #expect(abs(s.predicted - p.predicted) < 1e-9, "\(key): swift \(s.predicted) python \(p.predicted)")
            #expect(s.truth == p.truth, "\(key)")
        }
        // The fixture exists to exercise the clamp and the anchor; make sure it still does.
        #expect(f.rows.contains { $0.predicted == 100 })
    }

    @Test func displayedValueAnchorsUpOnlyAndClampsToUsedAndCap() {
        let start = Date(timeIntervalSince1970: 1_752_000_000)
        let reset = start.addingTimeInterval(5 * 3600)
        let now = start.addingTimeInterval(3600)
        let partial = BurnTrajectory.PartialCycle(
            samples: [.init(at: start, usedPercentage: 0), .init(at: now, usedPercentage: 30)],
            now: now, cycleStart: start, resetsAt: reset)
        // A fit sitting 10 under the live value is shifted up by 10.
        let under: (Date) -> Double = { $0 == now ? 20 : 50 }
        #expect(BurnTrajectory.displayedAtReset(under, partial: partial) == 60)
        // One sitting above it is not shifted down.
        let over: (Date) -> Double = { $0 == now ? 40 : 50 }
        #expect(BurnTrajectory.displayedAtReset(over, partial: partial) == 50)
        // Past the cap clamps to 100; below the meter clamps to the meter.
        #expect(BurnTrajectory.displayedAtReset({ $0 == now ? 30 : 250 }, partial: partial) == 100)
        #expect(BurnTrajectory.displayedAtReset({ $0 == now ? 30 : 10 }, partial: partial) == 30)
    }

    @Test func everyRecordRowIsTheDisplayedValueAtItsCut() throws {
        let cycles = Self.cycles(try Self.fixture())
        let out = EngineSelfEval.newOutcomesRL(
            window: "five_hour", cycles: cycles, activityGrid: [], calendar: Self.utc,
            existingKeys: [], includeDiurnal: false)
        let byPeriod = Dictionary(uniqueKeysWithValues: cycles.map { (EngineSelfEval.periodKeyRL($0.resetsAt), $0) })
        let models = Dictionary(uniqueKeysWithValues: BurnTrajectory.defaultModels.map { ($0.id, $0) })
        #expect(!out.isEmpty)
        for o in out {
            #expect(EngineSelfEval.isCurrentRLBucket(o.bucket))
            let cycle = try #require(byPeriod[o.periodKey])
            let cf = try #require(Double(o.bucket.dropFirst(4).prefix(4)))
            let now = cycle.cycleStart.addingTimeInterval(cycle.resetsAt.timeIntervalSince(cycle.cycleStart) * cf)
            let partial = BurnTrajectory.PartialCycle(
                samples: cycle.samples, now: now, cycleStart: cycle.cycleStart, resetsAt: cycle.resetsAt)
            let proj = try #require(models[o.method]?.fit(partial))
            #expect(o.predicted == BurnTrajectory.displayedAtReset(proj, partial: partial))
        }
    }

    @Test func onlyTheCurrentBucketVersionCounts() {
        #expect(EngineSelfEval.isCurrentRLBucket(EngineSelfEval.rlBucket(0.2)))
        #expect(!EngineSelfEval.isCurrentRLBucket("cut=0.20"))          // v1: the raw extrapolation
        #expect(!EngineSelfEval.isCurrentRLBucket("cut=0.25|all"))      // an end-of-day bucket
    }

    @Test func weeklySelectionRanksByTheMeanNotTheZeroMedian() {
        // Most weekly cycles end at the cap, where every model's displayed value
        // is exactly right: the medians tie at 0 and only the mean separates
        // the model that misses badly when it misses.
        func rows(_ method: String, _ errors: [Double]) -> [EngineSelfEval.Record] {
            errors.enumerated().map { i, e in
                .init(method: method, bucket: EngineSelfEval.rlBucket(0.2), periodKey: "p\(i)",
                      predicted: 100 - e, truth: 100)
            }
        }
        let records = rows("linear-recent", [0, 0, 0, 30, 40]) + rows("saturating", [0, 0, 0, 4, 6])
        let complexity = ["linear-recent": 1, "saturating": 3]
        #expect(EngineSelfEval.bestMethod(from: records, complexity: complexity) == "linear-recent")
        #expect(EngineSelfEval.bestMethod(from: records, complexity: complexity, weekly: true) == "saturating")
        let acc = EngineSelfEval.accuracy(surface: "rl-seven_day", from: records, weekly: true)
        #expect(acc.methods.first { $0.method == "saturating" }?.typicalAbsError == 2)
    }

    @Test func theSecondRefitScoresCyclesOlderThanTheRefitWindow() async throws {
        let container = try PacerStore.makeInMemoryContainer()
        let cal = Self.utc
        let duration: TimeInterval = 5 * 3600
        let now = Date(timeIntervalSince1970: 1_752_000_000)
        // Six 5-hour cycles 40 days back (outside the 32-day refit read), six recent.
        let seed = ModelContext(container)
        // Typed and built in steps: as one chained expression it timed out the
        // macOS 26 runner's type checker.
        var starts: [Date] = []
        for k in 0..<6 {
            let i = Double(k)
            starts.append(now.addingTimeInterval(-40 * 86400 + i * duration))
            starts.append(now.addingTimeInterval(-(7 - i) * duration))
        }
        for start in starts {
            let reset = start.addingTimeInterval(duration)
            var t = start, pct = 0.0
            while t <= reset {
                seed.insert(RateLimitSample(sampledAt: t, window: "five_hour", usedPercentage: min(80, pct),
                                            resetsAt: reset, source: "oauth"))
                t = t.addingTimeInterval(600); pct += 2.5
            }
        }
        try seed.save()

        let cutoffKey = EngineSelfEval.periodKeyRL(now.addingTimeInterval(-32 * 86400))
        func oldRows() throws -> Int {
            try ModelContext(container).fetch(FetchDescriptor<EngineEvalOutcome>()).filter {
                $0.surface == EngineSelfEval.rlSurface("five_hour") && $0.periodKey < cutoffKey
            }.count
        }
        let engine = UsageIntelligenceEngine(modelContainer: container)
        await engine.recompute(now: now, calendar: cal)
        #expect(try oldRows() == 0)          // the first refit reads 32 days only, and stays fast
        await engine.recompute(now: now, calendar: cal)
        #expect(try oldRows() > 0)           // the second one scores the full history
        let rows = try ModelContext(container).fetch(FetchDescriptor<EngineEvalOutcome>())
        #expect(rows.filter { $0.surface.hasPrefix("rl-") }.allSatisfy { EngineSelfEval.isCurrentRLBucket($0.bucket) })
    }
}
